from pathlib import Path
p=Path('frontend/index.html')
if not p.exists():
    p=Path('../frontend/index.html')
if not p.exists():
    raise SystemExit('ERROR: frontend/index.html not found. Run this from the project root or backend folder.')
s=p.read_text(encoding='utf-8')
marker='/* ===== Secure private-file viewer/download fix ====='
if marker in s:
    print('Secure file fix is already installed. No changes made.')
else:
    patch='/* ===== Secure private-file viewer/download fix =====\n   Private files are served from /api/files/:id and require the current Bearer token.\n   Normal href/src navigation cannot attach that header, so all private-file UI actions\n   use fetch() with the authenticated token and a temporary Blob URL instead. */\nfunction ssIsPrivateFile(src){return String(src||\'\').startsWith(\'/api/files/\');}\nasync function ssOpenFile(src,download,filename){\n  src=String(src||\'\'); if(!src)return toast(\'File not available\');\n  if(!ssIsPrivateFile(src)){\n    if(download){const a=document.createElement(\'a\');a.href=src;a.download=filename||\'file\';a.target=\'_blank\';a.rel=\'noopener\';document.body.appendChild(a);a.click();a.remove();}\n    else window.open(src,\'_blank\',\'noopener\');\n    return;\n  }\n  const token=sessionStorage.getItem(\'smartSchoolToken\');\n  if(!token)return toast(\'Your session has expired. Please log in again.\');\n  const popup=download?null:window.open(\'about:blank\',\'_blank\');\n  try{\n    const u=src+(src.includes(\'?\')?\'&\':\'?\')+\'inline=\'+(download?\'0\':\'1\');\n    const r=await fetch(u,{headers:{Authorization:\'Bearer \'+token}});\n    if(!r.ok)throw new Error(\'Unable to access file (\'+r.status+\')\');\n    const blob=await r.blob(),url=URL.createObjectURL(blob);\n    if(download){const a=document.createElement(\'a\');a.href=url;a.download=filename||\'file\';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}\n    else if(popup){popup.location.href=url;setTimeout(()=>URL.revokeObjectURL(url),60000);}\n    else window.open(url,\'_blank\',\'noopener\');\n  }catch(err){if(popup)popup.close();toast(err.message||\'Unable to open file\');}\n}\n\n/* Make every existing private-file <a> work without changing the rest of the UI. */\ndocument.addEventListener(\'click\',function(e){\n  const a=e.target.closest(\'a[href^="/api/files/"]\');\n  if(!a)return;\n  e.preventDefault();\n  ssOpenFile(a.getAttribute(\'href\'),false,a.getAttribute(\'download\')||\'file\');\n});\n\n/* Fee proof: secure View + Download instead of an unauthenticated <img src>. */\nfunction viewFeeProof(id){\n  const f=fees.find(x=>String(x.id)===String(id));\n  if(!f?.paymentProof)return toast(\'No payment proof uploaded\');\n  modal(\'Payment Proof\',\'<div style="text-align:center"><p><b>\'+esc(feeStudentName(f.studentId))+\'</b></p><p class="muted">The payment screenshot is securely stored.</p><div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap"><button class="btn light" type="button" data-file-url="\'+esc(f.paymentProof)+\'" onclick="ssOpenFile(this.dataset.fileUrl,false,\\\'payment-proof\\\')">👁 View Screenshot</button><button class="btn light" type="button" data-file-url="\'+esc(f.paymentProof)+\'" onclick="ssOpenFile(this.dataset.fileUrl,true,\\\'payment-proof\\\')">⬇ Download Screenshot</button></div></div>\');\n}\n\n/* Admin verification dialog: the proof link is now intercepted by the secure-file handler above. */\n\n/* Events: replace direct download links for private media with authenticated buttons. */\nasync function viewEventMedia(src,type){\n  const title=type===\'video\'?\'View Event Video\':\'View Event Photo\';\n  if(ssIsPrivateFile(src)){\n    modal(title,\'<div style="text-align:center"><p class="muted">Secure event media</p><div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap"><button class="btn light" type="button" onclick="ssOpenFile(\\\'\'+esc(src)+\'\\\',false,\\\'event-media\\\')">👁 View</button><button class="btn light" type="button" onclick="ssOpenFile(\\\'\'+esc(src)+\'\\\',true,\\\'event-media\\\')">⬇ Download</button></div></div>\');\n    return;\n  }\n  modal(title,type===\'video\'?\'<video controls autoplay style="width:100%;max-height:65vh" src="\'+esc(src)+\'"></video><div style="margin-top:10px;text-align:center"><button class="btn light" type="button" onclick="ssOpenFile(\\\'\'+esc(src)+\'\\\',true,\\\'event-video.mp4\\\')">⬇ Download Video</button></div>\':\'<img src="\'+esc(src)+\'" alt="Event photo" style="width:100%;max-height:65vh;object-fit:contain"><div style="margin-top:10px;text-align:center"><button class="btn light" type="button" onclick="ssOpenFile(\\\'\'+esc(src)+\'\\\',true,\\\'event-photo.jpg\\\')">⬇ Download Photo</button></div>\');\n}\n\n/* Certificates can also be private FileAsset URLs; the global link interceptor handles View/Download. */'
    needle='</script></body></html>'
    if needle not in s:
        raise SystemExit('ERROR: expected frontend ending was not found; file was not changed.')
    backup=p.with_suffix('.index-backup.html')
    backup.write_text(s,encoding='utf-8')
    p.write_text(s.replace(needle,patch+'\n'+needle,1),encoding='utf-8')
    print('SUCCESS: existing frontend/index.html patched.')
    print('Backup:',backup)
